  "code": "def parse_port(text: str) -> int:
    if not text:
        raise ValueError("Port string must not be empty")

    # Check for ASCII decimal digits only
    for ch in text:
        if ch < '0' or ch > '9':
            raise ValueError("Invalid character in port string")

    # Convert to integer
    try:
        port = int(text)
    except ValueError:
        raise ValueError("Invalid port number")

    # Check range 1-65535
    if port < 1 or port > 65535:
        raise ValueError("Port number out of range")

    return port",
  "summary": "解析端口号字符串，仅接受1到65535之间的ASCII十进制数字，拒绝空白、符号、Unicode数字、零及越界值，允许前导零。"
